//! A hand-arranged order reconciles, and draws, as astrid-web's does.
//!
//! `contracts/fixtures/manual-order.json` is generated by running `sanitizeManualOrder`
//! (`lib/list-manual-order.ts`) and the "manual" sort (`lib/task-sort.ts`) over a case table.
//! Tasks an arrangement does not name come newest first, as on iOS; that was D33's dispute until
//! astrid-web adopted it (AWTD-1583), and those cases are ordinary ones now.

mod common;

use serde_json::Value;

const FIXTURE: &str = include_str!("../../../contracts/fixtures/manual-order.json");

fn strings(value: &Value) -> Vec<String> {
    value
        .as_array()
        .expect("an array")
        .iter()
        .map(|v| v.as_str().expect("a string").to_string())
        .collect()
}

/// Both halves through the stateless door (task `c2109ff8`), because both are asked by a client
/// that does not link this crate: web reconciles on every drop, and the VS Code board draws the
/// arranged order.
fn answer(case: &Value) -> Vec<String> {
    if case["id"].as_str().unwrap().starts_with("reconcile/") {
        strings(&common::ask(serde_json::json!({
            "kind": "manualOrder",
            "requested": case["requested"],
            "inListByCreation": case["inListByCreation"],
        })))
    } else {
        let answered = common::ask(serde_json::json!({
            "kind": "rows",
            "now": "2026-10-17T12:00:00.000Z",
            "list": { "id": "l", "sortBy": "manual", "manualSortOrder": case["manualOrder"] },
            "tasks": case["tasks"],
            "idsOnly": true,
        }));
        strings(&answered["ids"])
    }
}

fn web(case: &Value) -> Vec<String> {
    strings(if case["stored"].is_array() {
        &case["stored"]
    } else {
        &case["shown"]
    })
}

#[test]
fn every_undisputed_case_answers_as_web_does() {
    let fixture: Value = serde_json::from_str(FIXTURE).expect("the fixture parses");
    let cases = fixture["cases"].as_array().unwrap();
    assert!(cases.len() >= 14);
    let failures: Vec<String> = cases
        .iter()
        .filter_map(|case| {
            let ours = answer(case);
            (ours != web(case))
                .then(|| format!("{}: web {:?}, core {ours:?}", case["id"], web(case)))
        })
        .collect();
    common::no_failures("manual-order.json", &failures);
}
